toolUseResult.stdout:
// Google スライドの資料の読み込みの結果 build/presentation.json の型と検査 (計画の KTD10・U6)。
// スキル publish では、Claude が Google スライドのコネクタで、項目を指定して (field mask は定数 PRESENTATION_FIELDS) 資料を読み込み、
// 結果をそのまま build/presentation.json に書く。サブコマンド requests は、このファイルの検査を通った値だけを使う。
// 形は、U11 の確認 (Issue #251 のコメント) で得た読み込みの結果に合わせた。

/**
 * 読み込みで指定する項目 (Google スライドの API の field mask)。
 * U11 で確認した項目に、マスターの配色 (pageProperties.colorScheme) を足した。配色は、テーマの色と比べ、違うマスターだけを変えるために読む。
 * サブコマンド requests の --help で示す
 */
export const PRESENTATION_FIELDS =
  "revisionId,masters(objectId,pageProperties.colorScheme)," +
  "slides(objectId,slideProperties(masterObjectId,notesPage(notesProperties.speakerNotesObjectId," +
  "pageElements(objectId,shape(shapeType,placeholder.type,text.textElements.textRun.content)))))";

/** 検査の誤りに添える、build/presentation.json に期待する形。サブコマンド requests の --help でも示す */
export const PRESENTATION_SHAPE = `{
  "revisionId": "<資料の版の ID>",
  "masters": [
    { "objectId": "<マスターの ID>",
      "pageProperties": { "colorScheme": { "colors": [ { "type": "DARK1", "color": { "red": 0〜1, "green": 0〜1, "blue": 0〜1 } }, … ] } } }
  ],
  "slides": [
    { "objectId": "<スライドの ID>",
      "slideProperties": { "notesPage": {
        "notesProperties": { "speakerNotesObjectId": "<ノートの欄の ID>" },
        "pageElements": [ { "objectId": "<ノートの欄の ID>", "shape": { "text": { "textElements": [ { "textRun": { "content": "…" } } ] } } }, … ]
      } } }
  ]
}
masters は 1 つ以上。slides は資料のスライドの順序で、空でもよい。ノートの欄が空なら、その要素に text が無い。
色の成分が 0 なら、その成分は無くてよい。`;

/** 色の 3 つの成分 (0〜1)。 */
export interface RgbColor {
  red: number;
  green: number;
  blue: number;
}

/** 読み込んだマスター。colors は、配色の種類 (DARK1・ACCENT1 など) ごとの色。 */
export interface PresentationMaster {
  objectId: string;
  colors: ReadonlyMap<string, RgbColor>;
}

/**
 * 読み込んだスライド。notesText はノートの欄の文 (textRun の content をつないだもの。Google スライドは末尾に改行を付ける)。
 * 要素に text が無ければ null。text があっても文を持たない (段落の始まりだけか、改行だけの) ことがあるので、
 * 欄が空かどうかは、この値ではなく末尾の改行を除いた文で決める (ファイル src/gslides/notes.ts。計画の KTD10)
 */
export interface PresentationSlide {
  objectId: string;
  notesObjectId: string;
  notesText: string | null;
}

/** 検査を通った読み込みの結果。slides の順序は、資料のスライドの順序。 */
export interface Presentation {
  revisionId: string;
  masters: PresentationMaster[];
  slides: PresentationSlide[];
}

export type ParsePresentationResult = { ok: true; presentation: Presentation } | { ok: false; errors: string[] };

type Json = Record<string, unknown>;

function isObject(v: unknown): v is Json {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

/** 読み込みの結果の検査。誤りは、場所 (JSON の中のパス) を付けてすべて集める */
class Checker {
  readonly errors: string[] = [];

  fail(path: string, message: string): void {
    this.errors.push(`${path}: ${message}`);
  }

  object(v: unknown, path: string): Json | null {
    if (isObject(v)) return v;
    this.fail(path, v === undefined ? "無い" : "オブジェクトではない");
    return null;
  }

  array(v: unknown, path: string): unknown[] | null {
    if (Array.isArray(v)) return v as unknown[];
    this.fail(path, v === undefined ? "無い" : "配列ではない");
    return null;
  }

  string(v: unknown, path: string): string | null {
    if (typeof v === "string" && v !== "") return v;
    this.fail(path, v === undefined ? "無い" : "空でない文字列ではない");
    return null;
  }
}

function parseColor(c: Checker, v: unknown, path: string): RgbColor | null {
  const o = c.object(v, path);
  if (o === null) return null;
  const color: RgbColor = { red: 0, green: 0, blue: 0 };
  let ok = true;
  for (const name of ["red", "green", "blue"] as const) {
    const value = o[name];
    // 成分が 0 のときは、読み込みの結果からその成分が除かれる (U11 の確認)
    if (value === undefined) continue;
    if (typeof value !== "number" || value < 0 || value > 1) {
      c.fail(`${path}.${name}`, "0〜1 の数ではない");
      ok = false;
      continue;
    }
    color[name] = value;
  }
  return ok ? color : null;
}

function parseMaster(c: Checker, v: unknown, path: string): PresentationMaster | null {
  const o = c.object(v, path);
  if (o === null) return null;
  const objectId = c.string(o["objectId"], `${path}.objectId`);
  const pageProperties = c.object(o["pageProperties"], `${path}.pageProperties`);
  const scheme = pageProperties === null ? null : c.object(pageProperties["colorScheme"], `${path}.pageProperties.colorScheme`);
  const list = scheme === null ? null : c.array(scheme["colors"], `${path}.pageProperties.colorScheme.colors`);
  if (objectId === null || list === null) return null;
  const colors = new Map<string, RgbColor>();
  list.forEach((item, i) => {
    const p = `${path}.pageProperties.colorScheme.colors[${String(i)}]`;
    const entry = c.object(item, p);
    if (entry === null) return;
    const type = c.string(entry["type"], `${p}.type`);
    const color = parseColor(c, entry["color"], `${p}.color`);
    if (type !== null && color !== null) colors.set(type, color);
  });
  return { objectId, colors };
}

/** ノートの欄の要素の text から、文をつないで返す。text が無ければ null */
function notesText(c: Checker, element: Json, path: string): string | null {
  const shape = c.object(element["shape"], `${path}.shape`);
  if (shape === null) return null;
  const text = shape["text"];
  if (text === undefined) return null;
  const body = c.object(text, `${path}.shape.text`);
  const elements = body === null ? null : c.array(body["textElements"], `${path}.shape.text.textElements`);
  if (elements === null) return null;
  // 段落の始まりを表す要素は、項目の指定で中身が除かれて {} になる (U11 の確認)。textRun を持つ要素だけをつなぐ
  return elements
    .map((e) => (isObject(e) && isObject(e["textRun"]) && typeof e["textRun"]["content"] === "string" ? e["textRun"]["content"] : ""))
    .join("");
}

function parseSlide(c: Checker, v: unknown, path: string): PresentationSlide | null {
  const o = c.object(v, path);
  if (o === null) return null;
  const objectId = c.string(o["objectId"], `${path}.objectId`);
  const props = c.object(o["slideProperties"], `${path}.slideProperties`);
  const notesPage = props === null ? null : c.object(props["notesPage"], `${path}.slideProperties.notesPage`);
  if (notesPage === null) return null;
  const notesPath = `${path}.slideProperties.notesPage`;
  const notesProperties = c.object(notesPage["notesProperties"], `${notesPath}.notesProperties`);
  const notesObjectId =
    notesProperties === null
      ? null
      : c.string(notesProperties["speakerNotesObjectId"], `${notesPath}.notesProperties.speakerNotesObjectId`);
  const elements = c.array(notesPage["pageElements"], `${notesPath}.pageElements`);
  if (objectId === null || notesObjectId === null || elements === null) return null;
  const index = elements.findIndex((e) => isObject(e) && e["objectId"] === notesObjectId);
  const element = elements[index];
  if (!isObject(element)) {
    c.fail(`${notesPath}.pageElements`, `ノートの欄の ID ${notesObjectId} を持つ要素が無い`);
    return null;
  }
  const text = notesText(c, element, `${notesPath}.pageElements[${String(index)}]`);
  return { objectId, notesObjectId, notesText: text };
}

/**
 * build/presentation.json の内容 (JSON.parse の結果) を検査する。
 * 形が違えば、場所を付けた誤りをすべて返す (表示するときは PRESENTATION_SHAPE を添える)
 */
export function parsePresentation(json: unknown): ParsePresentationResult {
  const c = new Checker();
  const root = c.object(json, "(全体)");
  if (root === null) return { ok: false, errors: c.errors };
  const revisionId = c.string(root["revisionId"], "revisionId");
  const masterList = c.array(root["masters"], "masters");
  if (masterList?.length === 0) c.fail("masters", "空 (マスターが 1 つ以上要る)");
  const slideList = c.array(root["slides"], "slides");
  const masters = (masterList ?? []).map((m, i) => parseMaster(c, m, `masters[${String(i)}]`));
  const slides = (slideList ?? []).map((s, i) => parseSlide(c, s, `slides[${String(i)}]`));
  const ids = new Set<string>();
  for (const [i, s] of slides.entries()) {
    if (s === null) continue;
    if (ids.has(s.objectId)) c.fail(`slides[${String(i)}].objectId`, `スライドの ID ${s.objectId} が 2 回ある`);
    ids.add(s.objectId);
  }
  if (c.errors.length > 0 || revisionId === null) return { ok: false, errors: c.errors };
  return {
    ok: true,
    presentation: {
      revisionId,
      masters: masters.filter((m) => m !== null),
      slides: slides.filter((s) => s !== null),
    },
  };
}
# Google スライドの扱い

スキル `publish` が、Google スライドのコネクタで資料を作り、読み込み、指示を送り、画像で確認するときの方法。入口のサブコマンドの引数・出力・終了コードは書かない。`node <プラグインのディレクトリ>/src/cli.ts <サブコマンド> --help` の出力を参照する (特に `requests --help` が、読み込みで指定する項目と、`build/presentation.json` の期待する形を示す)。

この文書で使う語:

- **コネクタ**: Claude のデスクトップアプリで有効にする、Google ドライブと Google スライドを操作するツールの集まり。
- **資料の ID**: Google スライドの資料の URL の `/d/` の後の部分。サブコマンド `check-outline` が、構成案の URL から取り出して示す。
- **指示のファイル**: サブコマンド `requests` が書く、Google スライドの API のメソッド `presentations.batchUpdate` に渡す指示の配列のファイル (`build/requests-<番号>.json` と `build/requests-notes-<番号>.json`)。

## 使うツール

| コネクタ | ツール | 使う場面 |
| --- | --- | --- |
| Google ドライブ | `create_file` | 新しい空の資料を作る |
| Google スライド | `read_presentation` | 資料を読み込む (項目を指定する) |
| Google スライド | `update_presentation` | 指示のファイルを送る |
| Google スライド | `read_slide_page_thumbnail` | スライドの画像の URL を得る |

ツールの名前は、使う環境で違うことがある。読み込まれていないツールは、ツールの検索 (例: 「google slides」) で読み込む。検索で見つからなければ、使えるツールを一覧にしてから、無いと判断する。Google スライドのコネクタが無ければ、別の方法 (PowerPoint のファイルを Google ドライブにアップロードして変換するなど) を試さずに中断し、有効にするよう利用者に求める。設定されているが無効なら、そのチャットのコネクタの設定で有効にしてもらい、設定されていなければ、追加するコネクタを示す。PowerPoint のファイル (`build/deck.pptx`) を渡すのは、利用者が選んだときだけ。

## 新しい資料を作る

構成案に Google スライドの URL の行が無いときだけ作る。

1. `create_file` を、`title` を構成案の題名、`contentMimeType` を `application/vnd.google-apps.presentation` にして実行する (内容は渡さない)。
2. 結果のファイルの ID から、URL `https://docs.google.com/presentation/d/<ファイルの ID>/edit` を作り、すぐにサブコマンド `write-info` の `--google-slides` で構成案に書き込む。後の手順で失敗しても、作った資料の URL が構成案に残るようにするため。
3. 新しい資料には、タイトルのスライドが 1 枚ある。このスライドは、サブコマンド `requests` が最初の指示のファイルで消す。手で消さない。

## 資料を読み込み、`build/presentation.json` に書く

1. `read_presentation` を、`presentationId` を資料の ID、`fields` を `requests --help` の「読み込みで指定する項目」の文字列 1 つの配列にして実行する。項目を指定しない読み込みは、資料のすべてのレイアウトとマスターを返し、大きくなるので行わない。
2. 結果の JSON を、加工せずに資料のディレクトリの `build/presentation.json` に書く。アプリが結果をファイルに保存したときは、そのファイルをコピーする。結果が会話に返ったときは、項目を足したり、消したり、並べ替えたりせずに、そのまま書く。
3. 期待する形に合わなければ、`requests` が場所と期待する形を示して終了コード 2 になる。読み込みの項目の指定が `requests --help` と同じかを確認してから、読み込みをやり直す。

## 指示のファイルを送る

`requests` は、送る指示のファイルを、送る順に出力に示す。1 つのファイルを送るときは、次のとおりにする。

1. ファイルの内容 (JSON の配列) を Bash の出力として読む (例: `cat <資料のディレクトリ>/build/requests-1.json`)。ファイルは 20,000 字以下に分けてあり、Bash の出力の上限に収まる。
2. `update_presentation` を、`presentationId` を資料の ID、`requests` をファイルの配列そのもの、`writeControl.requiredRevisionId` を送る直前に読み込んだ `build/presentation.json` の `revisionId` にして実行する。指示の中身を変えない。`writeControl` を外さない。
3. 送ると資料の版が変わる。次のファイルを送る前に、資料を読み込み直す。書き込みの応答に含まれる版の ID は使わない。

スキル `publish` は、「資料を読み込んで `build/presentation.json` に書く → `requests` を実行する → 出力の先頭のファイルだけを送る」を、`requests` が「送る指示は無い」と示すまで繰り返す。送るたびに `revisionId` が変わり、作ったスライドの発表者ノートの欄の ID も、作った後に読み込まないと分からないため。作る・作り直すスライドのノートの指示は、スライドを作った後の繰り返しで、ノートの指示のファイルとして出る。

`--recreate-all` を付けたときだけは、`requests` を 1 回だけ実行し、書いたスライドの指示のファイルを、書いた順にすべて送る (どのファイルも、送る直前に資料を読み込み、その `revisionId` を付ける。このときの読み込みは、項目 `revisionId` だけでよい)。理由は `requests --help` の `--recreate-all` の説明にある。送り終えたら、`--recreate-all` を付けずに上の繰り返しを行い、ノートを入れる。

### 送ったときの誤り

- **`The required revision ID ... does not match the latest revision.`**: 読み込んだ後に、資料が変わった (利用者が編集したなど)。何も適用されていない。資料を読み込み直し、`requests` からやり直す。
- **ほかの誤り**: 1 回の送信の指示は、1 つでも誤りがあれば、どれも適用されない。指示のファイルを手で直して送らずに、誤りの文と、送ったファイルのパスを利用者に示して中断する。ツールの不具合の可能性があるため。

途中で中断しても、もう一度 `publish` を実行すれば、資料のスライドの ID から残りの作業が決まり、残りだけを行う。ただし、`--recreate-all` の途中で中断したときは、構成案の slide-deck の版の行をまだ書き込んでいないので、もう一度すべてを作り直すかを質問することになる。

## ID の形

- **スライドの ID**: `sd_<キー>_<ハッシュ値>`。ハッシュ値は、題名・一言・図の要素とテーマのフォントから求めた 16 進数 10 文字で、位置と発表者ノートを含めない。題名・一言・図のどれかを変えるとハッシュ値が変わり、スライドを作り直す。ノートだけを変えたときは、作り直さずにノートだけを入れ直す。
- **図形の ID**: `<スライドの ID>_<番号>` (番号は 3 桁まで)。
- **キーの無いスライド**: ID が `sd_<キー>_<ハッシュ値>` の形でないスライド (利用者が Google スライドで足したもの)。`requests` は内容を変えず、直前のキーのあるスライドと一緒に動かす。
- **手で直した内容**: キーのあるスライドを利用者が Google スライドで直しても、ID は変わらない。そのスライドを作り直すと、手で直した内容は失われる。消すときも同じ。

## 画像で確認する

1. スライドごとに、`read_slide_page_thumbnail` を、`presentationId` を資料の ID、`pageId` をスライドの ID、`thumbnailProperties.thumbnailSize` を `MEDIUM` (幅 800 ピクセル) にして実行し、画像の URL (`contentUrl`) を得る。スライドの ID は、最後に書いた `build/presentation.json` の配列 `slides` にある。
2. 画像の URL を 6 枚ずつ、画像をまとめるツール `python/slide_deck_tools/thumbs_grid.py` に、キャッシュの venv の Python で渡す。venv のパスは、サブコマンド `setup status` の出力の「venv」の行にある。

   ```bash
   <venv のパス>/bin/python <プラグインのディレクトリ>/python/slide_deck_tools/thumbs_grid.py <資料のディレクトリ>/build/thumbs-1.png <URL> <URL> ...
   ```

   引数・出力・終了コードは、`thumbs_grid.py --help` の出力を参照する。終了コード 2 (取得できない URL など) なら、誤りの文を利用者に示し、画像での確認をしていないことを伝える。
3. 書いた画像を読み、最後の 1 文字だけの行・はみ出し・位置のずれ・重なりを探す。

## Google スライドの API への対処

PowerPoint のファイルと同じ見た目にするために、指示の作成で行っている対処。どれも理由をファイル [src/gslides/requests.ts](../src/gslides/requests.ts) のコメントに書いてある。画像で見つけた違いが、ここにある対処の結果かを判断するのに使う。

| 対処 | 理由 |
| --- | --- |
| 図形の大きさを、基準の大きさ (3,000,000 EMU) と拡大率で表す | Google スライドは、読み込むと大きさを常にこの形で返す。後から大きさを変えるときに、読み込んだ拡大率をそのまま計算に使えるようにするため |
| 大きさが 0 の軸 (縦や横の線の幅か高さ) は、大きさ 0・拡大率 1 にする | 拡大率 0 を受け付けるかを確認していないため |
| 円・円柱・山形・五角形の矢印の中の文字は、図形に重ねた文字の箱にする | Google スライドは、これらの図形の中の文字を、図形の内側の狭い範囲に収めて折り返すため。重ねる文字の箱は、図形の外形に合わせる |
| 文字の箱は、データの余白の分だけ狭めてから、Google スライドの余白 (左右 0.1 インチ・上下 0.05 インチ) の分だけ広げる | Google スライドの余白は API で変えられないため。文字を配置する範囲がデータと一致する |
| 幅と高さのどちらも 1 インチより大きい角の丸い四角は、四角で描く | 丸みの大きさは API で変えられず、大きな箱では丸みが大きくなりすぎるため |
| 箇条書きの字下げを 16 ポイントにする | デフォルト値は大きく、幅の狭い箱では行が折り返されるため。はみ出しの見積もりと PowerPoint の書き出しも同じ値を使う |
| 書式の範囲に、段落の末尾の改行の文字を含める | 含めないと、改行の文字だけがデフォルトの大きさのまま残り、その行が高くなるため |
| 右から左・下から上への線は、拡大率を負にして描く | 線の向きは、始点と終点ではなく拡大率の正負で表すため |
| 線は `createLine` の `category` で作る | `lineCategory` は非推奨のため |
| マスターの配色を `updatePageProperties` の `colorScheme` で、テーマの 12 色に変える | 図形の色をテーマの色で指定しているので、配色を変えればすべてのスライドの色が変わるため。読み込んだ配色が同じなら変えない |
| スライドはレイアウト `BLANK` で作り、題名は普通の文字の箱にする | 元にしたツールと同じ作り方で、本物の Google スライドで動くことを確認した使い方の範囲に収まるため。題名の箱の位置と書式は、PowerPoint の題名の箱と同じ |

## できないこと

- **スライド番号**: API では付けない (レイアウト `BLANK` のスライドに、スライド番号のプレースホルダーを作れないため)。利用者に、メニューの「挿入 > スライド番号」で付けてもらう。
- **表・画像・グラフ**: スライドのデータが持たないので、作らない。
- **開いている資料への反映**: 利用者が開いている資料に、送った変更がすぐ表示されないことがある。表示されなければ、資料を再読み込みしてもらう。
